// wf.eval.retrieval > "Plan"
// Input: job row, dataset, queries with gold resolved against the current
// documents (eval.resolve_gold), embedding models and settings.
// Fails the job (throws) when the dataset is missing or a gold span cannot be
// located: numbers computed on a broken gold set would be wrong, not partial.
const row = $input.first().json;
if (!row.job_id) throw new Error('job not found or already finished');
if (!row.dataset_id) throw new Error(`dataset ${row.input.dataset} v${row.input.version} not found`);
const queries = row.queries || [];
if (!queries.length) throw new Error('dataset has no queries');
const problems = [];
for (const q of queries) {
  for (const g of q.gold || []) {
    if (!g.found) problems.push(`${q.external_id}: gold not found in ${g.source_key}`);
    else if (g.ambiguous) problems.push(`${q.external_id}: gold start quote occurs more than once in ${g.source_key}`);
  }
}
if (problems.length) throw new Error('gold set does not match the corpus: ' + problems.slice(0, 10).join('; ') + (problems.length > 10 ? ` (+${problems.length - 10})` : ''));

const configs = row.input.configs;
const cfg = {};
for (const [k, v] of Object.entries(row.cfg || {})) cfg[k] = v;
const models = (row.models || []).filter((m) => configs.some((c) => c.model === m.name && c.mode !== 'lexical'));
const out = [];
for (const m of models) {
  const size = m.endpoint === 'tei' ? Number(cfg['kb.batch_e5'] || 16) : Number(cfg['kb.batch_bge'] || 32);
  for (let i = 0; i < queries.length; i += size) {
    const b = queries.slice(i, i + size);
    const inputs = b.map((q) => (m.query_prefix || '') + q.query);
    const req = m.endpoint === 'tei'
      ? { url: `${cfg['kb.tei_base_url']}/embed`, body: { inputs, normalize: true, truncate: true } }
      : { url: `${cfg['ollama.base_url']}/api/embed`, body: { model: m.name, input: inputs, truncate: true } };
    out.push({ json: { model: m.name, endpoint: m.endpoint, dims: m.dims, query_ids: b.map((q) => q.id), ...req } });
  }
}
// A purely lexical matrix needs no embeddings: one placeholder item keeps the flow going.
if (!out.length) out.push({ json: { model: null, query_ids: [], url: null, body: null, none: true } });
out[0].json.t_embed_start = Date.now();
return out;

// wf.eval.retrieval > "Query vectors"
// Input: embedding answers for the query batches (text), in request order.
// Output: one item per configuration to evaluate, for the loop.
const plan = $('Start job').first().json;
const reqs = $('Plan').all().map((i) => i.json);
const t0 = reqs[0].t_embed_start;
const embedMs = Date.now() - t0;
const vectors = {};                       // model -> query_id -> vector
const perModelMs = {};
const answers = $input.all().map((i) => i.json.data);
reqs.forEach((req, i) => {
  if (req.none) return;
  const a = typeof answers[i] === 'string' ? JSON.parse(answers[i]) : answers[i];
  const vecs = req.endpoint === 'tei' ? a : a && a.embeddings;
  if (!Array.isArray(vecs) || vecs.length !== req.query_ids.length) throw new Error(`${req.model}: bad embedding answer for queries`);
  vectors[req.model] = vectors[req.model] || {};
  vecs.forEach((v, j) => {
    if (v.length !== req.dims) throw new Error(`${req.model}: dimension ${v.length}`);
    vectors[req.model][req.query_ids[j]] = v;
  });
});
const nModels = Object.keys(vectors).length || 1;
const nQueries = plan.queries.length;
// Embedding time is measured for all batches together; per query it is the
// average over models and queries (an amortised figure, D-040).
const embedMsPerQuery = embedMs / nModels / nQueries;
return plan.input.configs.map((c, i) => ({ json: {
  job_id: plan.job_id, dataset_id: plan.dataset_id, config_index: i,
  config: { ...c, jurisdiction: plan.input.jurisdiction, dataset: plan.input.dataset, version: plan.input.version,
            label: plan.input.label, overlap_fraction: Number((plan.cfg || {})['eval.relevance_overlap'] || 0.5) },
  git_sha: plan.input.git_sha, embed_ms_per_query: Math.round(embedMsPerQuery * 10) / 10,
  has_vectors: !!vectors[c.model],
} }));

// wf.eval.retrieval > "Expand queries"
// Input: the eval.runs row just created for one configuration.
// Output: one search request per query (eval.timed_search input).
const run = $input.first().json;
const plan = $('Start job').first().json;
const loopItem = $('Loop configs').first().json;
const c = loopItem.config;
// vectors are rebuilt from the embedding answers kept on "Query vectors"' input
const reqs = $('Plan').all().map((i) => i.json);
let answers = [];
try { answers = $('Embed queries').all().map((i) => i.json.data); } catch (e) { answers = []; }   // lexical-only matrix: never ran
const vec = {};
reqs.forEach((req, i) => {
  if (req.none || req.model !== c.model || answers[i] === undefined) return;
  const a = typeof answers[i] === 'string' ? JSON.parse(answers[i]) : answers[i];
  const vecs = req.endpoint === 'tei' ? a : a.embeddings;
  vecs.forEach((v, j) => { vec[req.query_ids[j]] = v; });
});
return plan.queries.map((q) => ({ json: { p: JSON.stringify({
  run_id: run.id, query_id: q.id, model: c.model, strategy: c.strategy, mode: c.mode, k: c.k,
  candidates: c.candidates, rrf_k: c.rrf_k, jurisdiction: c.jurisdiction, q_text: q.query,
  q_vec: c.mode === 'lexical' ? null : (vec[q.id] ? '[' + vec[q.id].join(',') + ']' : null),
}) } }));

// wf.eval.retrieval > "Score"
// Input: one eval.timed_search answer per query, in query order.
// Per-query metrics (eval/lib/metrics.js) and the run summary.
// Retrieval metrics with chunking-independent gold (spec 10.7).
// Gold: character spans in documents. A retrieved chunk is relevant when it
// overlaps a gold span of the same document by at least `frac` of the shorter
// of the two (D-039). Credit is given per gold span, so a chunker that cuts one
// gold passage into two chunks does not get two hits for it.
//
// retrieved: [{document_id, start_char, end_char}] in rank order
// gold:      [{document_id, start, end, found}]
// Returns per-query metrics: hit@k and recall@k for k in 1,3,5,10, mrr, ndcg@10,
// plus the rank of each credited gold span.

const KS = [1, 3, 5, 10];

function overlap(a0, a1, b0, b1) { return Math.max(0, Math.min(a1, b1) - Math.max(a0, b0)); }

function matchedGold(chunk, gold, frac) {
  const out = [];
  gold.forEach((g, gi) => {
    if (!g.found || g.document_id !== chunk.document_id) return;
    const ov = overlap(chunk.start_char, chunk.end_char, g.start, g.end);
    const shorter = Math.min(g.end - g.start, chunk.end_char - chunk.start_char);
    if (ov > 0 && ov >= frac * shorter) out.push(gi);
  });
  return out;
}

function queryMetrics(retrieved, gold, frac = 0.5) {
  const usable = gold.filter((g) => g.found);
  const G = usable.length;
  const credited = new Map();        // gold index -> rank (1-based)
  const relevant = [];               // per rank: chunk matches any gold span
  const gain = [];                   // per rank: 1 if it credits a new gold span
  retrieved.forEach((c, i) => {
    const m = matchedGold(c, gold, frac);
    relevant.push(m.length > 0);
    let g = 0;
    for (const gi of m) if (!credited.has(gi)) { credited.set(gi, i + 1); g = 1; }
    gain.push(g);
  });
  const out = { gold_spans: G, relevant_ranks: relevant.map((r, i) => (r ? i + 1 : null)).filter(Boolean) };
  for (const k of KS) {
    out[`hit@${k}`] = relevant.slice(0, k).some(Boolean) ? 1 : 0;
    const got = [...credited.values()].filter((r) => r <= k).length;
    out[`recall@${k}`] = G ? got / G : null;
  }
  const first = relevant.findIndex(Boolean);
  out.mrr = first >= 0 ? 1 / (first + 1) : 0;
  let dcg = 0, idcg = 0;
  for (let i = 0; i < Math.min(10, gain.length); i++) dcg += gain[i] / Math.log2(i + 2);
  for (let i = 0; i < Math.min(10, G); i++) idcg += 1 / Math.log2(i + 2);
  out['ndcg@10'] = idcg ? dcg / idcg : null;
  if (!G) for (const k of Object.keys(out)) if (/@|mrr/.test(k)) out[k] = null;
  return out;
}

if (typeof module !== 'undefined') module.exports = { queryMetrics, matchedGold, overlap, KS };

const plan = $('Start job').first().json;
const loopItem = $('Loop configs').first().json;
const run = $('Create run').first().json;
const frac = loopItem.config.overlap_fraction;
const answers = $input.all().map((i) => i.json.r);
if (answers.length !== plan.queries.length) throw new Error(`${answers.length} search answers for ${plan.queries.length} queries`);
const rows = [];
const sums = {};
let nScored = 0;
const lat = [];
plan.queries.forEach((q, i) => {
  const a = answers[i];
  const retrieved = (a.results || []).map((r) => ({
    chunk_id: r.chunk_id, rank: r.rank, score: r.score, dense_rank: r.dense_rank, lexical_rank: r.lexical_rank,
    dense_similarity: r.dense_similarity, document_id: r.document_id, start_char: r.start_char, end_char: r.end_char,
    source_key: r.source_key, source_type: r.source_type, article_ref: r.article_ref,
  }));
  const m = queryMetrics(retrieved, q.gold || [], frac);
  m.search_ms = a.ms;
  m.embed_ms_amortised = loopItem.config.mode === 'lexical' ? 0 : loopItem.embed_ms_per_query;
  lat.push(m.search_ms + m.embed_ms_amortised);
  if (m.gold_spans > 0) {
    nScored++;
    for (const [k, v] of Object.entries(m)) if (typeof v === 'number' && /@|mrr/.test(k)) sums[k] = (sums[k] || 0) + v;
  }
  rows.push({ run_id: run.id, query_id: q.id, retrieved, metrics: m });
});
const summary = { queries: plan.queries.length, scored: nScored };
for (const [k, v] of Object.entries(sums)) summary[k] = Math.round((v / nScored) * 10000) / 10000;
lat.sort((a, b) => a - b);
const pct = (p) => lat.length ? lat[Math.min(lat.length - 1, Math.ceil(p * lat.length) - 1)] : null;
summary.latency_ms_p50 = pct(0.5);
summary.latency_ms_p95 = pct(0.95);
return [{ json: { run_id: run.id, rows: JSON.stringify(rows), summary: JSON.stringify(summary) } }];

// wf.eval.retrieval > "Summarize"
// Input: one item per finished run (from "Store results"). Final job output.
const plan = $('Start job').first().json;
const runs = $input.all().map((i) => i.json).filter((r) => r.run_id);
return [{ json: {
  job_id: plan.job_id,
  status: runs.length === plan.input.configs.length ? 'succeeded' : 'failed',
  error: runs.length === plan.input.configs.length ? null : `${runs.length} of ${plan.input.configs.length} runs finished`,
  output: { dataset: plan.input.dataset, version: plan.input.version, queries: plan.queries.length,
            runs: runs.map((r) => ({ run_id: r.run_id, config: r.config, summary: r.summary })) },
} }];

// Worker workflows (wf.kb.ingest, wf.eval.retrieval) > "Job failed"
// Error output of any step after "Start job": the job ends as failed with the
// (redacted) error text, so it never stays "running" after a handled failure.
// Text of the error carried by an item on a node's error output.
// n8n puts either a string or an object {message, description, ...} in json.error.
function errorText(json) {
  const e = json && (json.error !== undefined ? json.error : json);
  if (e == null) return '';
  if (typeof e === 'string') return e;
  const parts = [e.message, e.description, e.cause && e.cause.message].filter((x) => typeof x === 'string' && x);
  return parts.length ? parts.join(' | ') : JSON.stringify(e);
}
// Postgres error details echo the offending value, e.g. Key (email)=(a@b.c).
// Values are removed before anything is logged.
function redactPg(msg) {
  return String(msg || '').replace(/\)=\([^)]*\)/g, ')=(redacted)');
}
if (typeof module !== 'undefined') module.exports = { errorText, redactPg };

const start = $('Start job').first().json;
const msg = redactPg(errorText($input.first().json)).slice(0, 500) || 'worker step failed without a message';
return [{ json: { job_id: start.job_id, status: 'failed', error: msg, output: { failed_step: true } } }];
